// The section of the symmetric regions found in the grid (one card per shape up to the 12 symmetries of the grid and
// per type, from the census of |x|, |d| <= 5000): each of its regions is verified by the site's own code before it is
// shown. At the stated cell (x, d) the flood fill gives the stated colour, area and genus, and the symmetry order (the
// number of the 12 symmetries of the grid that map the shape onto a translate of itself), recomputed here with the
// group generated by the turn (i, j) -> (i - j, i) and the mirror (i, j) -> (j, i), equals the stated one and the
// page's symmetryOrder. 751, 727 and 184 regions of the types +1, -1, 0, every cell with |x|, |d| <= 5000, no two
// cards of one type with the same shape up to the 12 symmetries, the optional short descriptions without size claims.

import { test } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import { fileURLToPath } from "node:url";
import * as gallery from "../../src/ui/gallery/model.mjs";
import { symmetryOrder, captionText } from "../../src/ui/gallery/model.mjs";
import { floodFill } from "../../src/core/regions.mjs";
import { cellKey, NEIGHBOURS } from "../../src/core/geometry.mjs";
import { hexDisc } from "../../src/core/shapes.mjs";

const read = (p) => JSON.parse(fs.readFileSync(fileURLToPath(new URL(`../../${p}`, import.meta.url)), "utf8"));
const found = read("data/gallery.json").found;

// the linear maps of the grid as integer matrices [[a, b], [c, d]]: (i, j) -> (a i + b j, c i + d j)
const apply = (m, [i, j]) => [m[0][0] * i + m[0][1] * j, m[1][0] * i + m[1][1] * j];
const mul = (m, n) => [[m[0][0] * n[0][0] + m[0][1] * n[1][0], m[0][0] * n[0][1] + m[0][1] * n[1][1]], [m[1][0] * n[0][0] + m[1][1] * n[1][0], m[1][0] * n[0][1] + m[1][1] * n[1][1]]];
const TURN = [[1, -1], [1, 0]];
const MIRROR = [[0, 1], [1, 0]];

// the group generated by TURN and MIRROR, by closure
function generate() {
  const key = (m) => m.flat().join(",");
  const out = new Map([[key([[1, 0], [0, 1]]), [[1, 0], [0, 1]]]]);
  let grew = true;
  while (grew) {
    grew = false;
    for (const m of [...out.values()]) {
      for (const g of [TURN, MIRROR]) {
        const p = mul(g, m);
        if (!out.has(key(p))) {
          out.set(key(p), p);
          grew = true;
        }
      }
    }
  }
  return [...out.values()];
}
const GROUP = generate();

function order(cells) {
  const norm = (cs) => {
    const mi = Math.min(...cs.map((c) => c[0]));
    const mj = Math.min(...cs.map((c) => c[1]));
    return cs.map(([i, j]) => cellKey(i - mi, j - mj)).sort().join(" ");
  };
  const base = norm(cells);
  return GROUP.filter((m) => norm(cells.map((c) => apply(m, c))) === base).length;
}

test("the group of the grid: 12 maps, each keeps the six neighbours of a cell", () => {
  assert.equal(GROUP.length, 12);
  const nb = new Set(NEIGHBOURS.map(([a, b]) => cellKey(a, b)));
  for (const m of GROUP) for (const v of NEIGHBOURS) assert.ok(nb.has(cellKey(...apply(m, v))));
  assert.equal(order([[0, 0]]), 12);
  assert.equal(symmetryOrder([[0, 0]]), 12);
  assert.equal(symmetryOrder(hexDisc(3)), 12);
  assert.equal(symmetryOrder([[0, 0], [1, 0]]), 4);
  assert.equal(symmetryOrder([[0, 0], [1, 0], [2, 0], [2, 1]]), order([[0, 0], [1, 0], [2, 0], [2, 1]]));
});

// the shape up to the 12 symmetries: the least of the normalised images under GROUP (a canonical text)
function canonical(cells) {
  const norm = (cs) => {
    const mi = Math.min(...cs.map((c) => c[0]));
    const mj = Math.min(...cs.map((c) => c[1]));
    return cs.map(([i, j]) => cellKey(i - mi, j - mj)).sort().join(" ");
  };
  return GROUP.map((m) => norm(cells.map((c) => apply(m, c)))).sort()[0];
}

test("the 1662 regions found in the grid: flood fill, colour, area, genus and symmetry order as stated, every cell inside |x|, |d| <= 5000, one card per shape up to the 12 symmetries and type", () => {
  assert.equal(found.length, 1662);
  const shapes = new Set();
  const counts = new Map();
  for (const c of found) {
    const f = floodFill(BigInt(c.x), BigInt(c.d), 200000);
    const what = `(${c.x}, ${c.d})`;
    assert.equal(f.complete, true, what);
    // the cells of the fill are offsets from (x, d)
    assert.ok(f.cells.every(([i, j]) => Math.abs(Number(c.x) + i) <= 5000 && Math.abs(Number(c.d) + j) <= 5000), `${what} inside the bound`);
    assert.equal(f.colour, c.colour, what);
    assert.equal(f.area, c.area, what);
    assert.equal(f.genus, c.genus, what);
    const sym = order(f.cells);
    assert.equal(sym, c.symmetry, what);
    assert.ok(sym >= 2, `${what} symmetric`);
    assert.equal(symmetryOrder(f.cells), sym, what);
    const key = `${c.colour} ${canonical(f.cells)}`;
    assert.equal(shapes.has(key), false, `${what}: its shape is on another card of its type`);
    shapes.add(key);
    const k = `type ${c.colour} symmetry ${sym}`;
    counts.set(k, (counts.get(k) || 0) + 1);
  }
  console.log([...counts].map(([k, n]) => `${k}: ${n} cards`).join("\n"));
});

test("751, 727 and 184 cards of the types +1, -1, 0, the card (40578, 120404) gone, descriptions without size claims", () => {
  assert.deepEqual([1, -1, 0].map((t) => found.filter((c) => c.colour === t).length), [751, 727, 184]);
  assert.equal(found.some((c) => c.x === "40578" && c.d === "120404"), false);
  const described = found.filter((c) => c.text !== undefined);
  // the 30 hand-made descriptions stay on the same regions
  assert.equal(described.length, 30);
  for (const c of described) {
    assert.ok(c.text.length >= 8 && c.text.length <= 70, c.text);
    assert.equal(/\b(largest|smallest|nearest|most|least|biggest)\b/i.test(c.text), false, c.text);
    assert.equal(/\b(green|red|blue)\b/i.test(c.text), false, c.text);
  }
  assert.equal(new Set(described.map((c) => c.text)).size >= 28, true);
  const star = found.find((c) => c.x === "1514" && c.d === "-1684");
  assert.equal(captionText(star, { area: 13, genus: 0, symmetry: 6 }), "13 cells | genus 0 | symmetry 6 | (1514, -1684)");
  assert.equal(captionText(star, { area: 1, genus: 0, symmetry: 12 }), "1 cell | genus 0 | symmetry 12 | (1514, -1684)");
  // no Gallery card links to another viewer (nor does the Explorer, tests/explore/url_state.test.mjs)
  assert.equal("AUTHOR_VIEWER_TITLE" in gallery, false);
  for (const f of ["src/ui/pages/gallery.mjs", "src/ui/gallery/cards.mjs", "styles/gallery.css"]) {
    assert.equal(/authorViewerHref|gal-ext|ai-me\.fr/.test(fs.readFileSync(fileURLToPath(new URL(`../../${f}`, import.meta.url)), "utf8")), false, f);
  }
});
